import{_t as e,it as t,n,ot as r,rt as i,xt as a}from"./chunks/framework.CJEq1BAB.js";var o=JSON.parse(`{"title":"Catalogs","description":"","frontmatter":{"title":"Catalogs","covers":{"screens":["SCR-020","SCR-028"],"stories":["US-046","US-049"]}},"headers":[],"relativePath":"usage/catalogs.md","filePath":"usage/catalogs.md"}`),s={name:`usage/catalogs.md`};function c(n,o,s,c,l,u){let d=a(`Screenshot`);return e(),i(`div`,null,[o[0]||=t(`<h1 id="catalogs" tabindex="-1">Catalogs <a class="header-anchor" href="#catalogs" aria-label="Permalink to “Catalogs”">​</a></h1><p>A catalog is a reusable table view of the repository. It shows the entities of one entity type as rows. You need the permission <code>entity:read</code> (for example the role <code>viewer</code>) to see catalogs and create personal ones; shared catalogs need <code>catalog:manage</code> (role <code>enterprise-architect</code>).</p><h2 id="create-a-catalog" tabindex="-1">Create a catalog <a class="header-anchor" href="#create-a-catalog" aria-label="Permalink to “Create a catalog”">​</a></h2><ol><li><p>Choose <em>Catalogs</em> in the header, then <em>New catalog</em>.</p></li><li><p>Fill in the dialog <em>New catalog</em>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>Name</td><td>required; unique within the instance, regardless of upper and lower case</td></tr><tr><td>Description</td><td>optional, up to 1000 characters</td></tr><tr><td>Primary entity type</td><td>required; its entities become the rows of the table</td></tr><tr><td>Visibility</td><td><em>Shared</em>: visible to all users of the instance (needs the permission to manage catalogs); <em>Personal</em>: visible only to you</td></tr><tr><td>Default join mode</td><td><em>Aggregate</em>: one row per entity, linked entities in one cell; <em>Rows</em>: one row per linked entity. Applies to joins added later</td></tr></tbody></table></li></ol>`,4),r(d,{name:`catalog-create`,alt:`Dialog New catalog with name, description, entity type and visibility`}),o[1]||=t(`<ol start="3"><li>Choose <em>Create catalog</em>. The new catalog opens.</li></ol><p>If the name is already taken, the dialog says so; choose another name. Without the permission to manage catalogs, <em>Shared</em> is not selectable.</p><h2 id="browse-a-catalog" tabindex="-1">Browse a catalog <a class="header-anchor" href="#browse-a-catalog" aria-label="Permalink to “Browse a catalog”">​</a></h2><p>The list <em>Catalogs</em> shows every catalog you may see, marked <em>Shared</em> or <em>Personal</em>. Open one to see its table:</p>`,4),r(d,{name:`catalogs`,alt:`List of catalogs`}),r(d,{name:`catalog-table`,alt:`Table of a catalog with application components`}),o[2]||=t(`<ul><li>As long as no columns are configured, the table shows the columns <em>Name</em> and – if the entity type has the property <em>Status</em> – <em>Status</em>.</li><li>Click a column header to sort: ascending, descending, and back to the default order.</li><li>The table shows 50 entries per page; use the pagination below the table to move between pages.</li><li>Sort and page are part of the address of the page. Back navigation, a reload or a shared link restore the same view; invalid values in the address are ignored and the first page is shown in the default order.</li><li>If the entity type has no entities yet, the table shows <em>No entries found</em>.</li><li>Another person&#39;s personal catalog cannot be opened; it behaves like a catalog that does not exist (<em>Catalog not found</em>).</li></ul><p>Through the API, <code>GET /catalogs/{id}/query</code> returns the same rows with the parameters <code>page</code> (from 0), <code>pageSize</code> (1–200, default 50) and <code>sort</code> (<code>{field}:{asc|desc}</code>).</p>`,2)])}var l=n(s,[[`render`,c]]);export{o as __pageData,l as default};